export const SAMPLE_DOCUMENTS=[
 {id:'permit',title:'Предоставление разрешения',focus:'Неопределённый срок и дополнительные документы',text:'УЧЕБНЫЙ ПРИМЕР. Не является действующим нормативным правовым актом.\nПроект административного регламента предоставления разрешения\n1. Заявление подаётся в уполномоченное подразделение лично или через электронную форму.\n2. К заявлению прилагается документ, подтверждающий полномочия представителя, если действует представитель.\n3. Сотрудник вправе потребовать иные документы по своему усмотрению.\n4. Рассмотрение заявления осуществляется в разумный срок.\n5. При положительном решении заявителю направляется разрешение.\n6. Отказ может быть обжалован в установленном порядке.',note:'Проверить, ограничено ли усмотрение по пункту 3; определён ли срок в пункте 4 или другом связанном акте. Без подходящих правовых источников это учебная гипотеза.'},
 {id:'exception',title:'Проверка связанного уточнения',focus:'Возражение Проверяющего к возможной находке',text:'УЧЕБНЫЙ ПРИМЕР. Не является действующим нормативным правовым актом.\nПроект порядка регистрации обращения\n1. Обращение регистрируется после поступления необходимых документов.\n2. Для целей пункта 1 необходимыми документами являются заявление и документ о полномочиях представителя при подаче через представителя. Иные документы не требуются.\n3. Регистрация производится не позднее следующего рабочего дня после поступления обращения.\n4. Уведомление о регистрации направляется заявителю в день регистрации.\n5. Основания отказа: отсутствие заявления либо отсутствие подтверждения полномочий представителя, когда обращение подано представителем.',note:'Фразу из пункта 1 нужно читать вместе с исчерпывающим перечнем пункта 2. Находка только по словам «необходимые документы» может быть ложной.'},
 {id:'appeal',title:'Порядок рассмотрения жалобы',focus:'Отсутствующая процедура и контроль смысла правки',text:'УЧЕБНЫЙ ПРИМЕР. Не является действующим нормативным правовым актом.\nПроект порядка рассмотрения жалоб\n1. Жалоба направляется в подразделение, принявшее оспариваемое решение.\n2. Подразделение рассматривает жалобу и принимает решение по существу.\n3. При необходимости срок рассмотрения может быть продлён руководителем без ограничения числа продлений.\n4. Решение сообщается заявителю удобным для подразделения способом.\n5. Материалы рассмотрения хранятся в подразделении.',note:'Исследовать определённость сроков, уведомления и процедуры. Редактор не должен самостоятельно придумывать срок или полномочия, которых нет в переданной нормативной базе.'},
 {id:'clear',title:'Определённая процедура',focus:'Проверка без заранее заданного нарушения',text:'УЧЕБНЫЙ ПРИМЕР. Не является действующим нормативным правовым актом.\nПроект регламента выдачи справки\n1. Заявление содержит ФИО заявителя и адрес для ответа.\n2. При подаче представителем прилагается подтверждение полномочий. Иные документы не требуются.\n3. Уполномоченное подразделение регистрирует заявление в день поступления.\n4. Справка направляется не позднее пяти рабочих дней после регистрации по адресу, указанному заявителем.\n5. При отсутствии сведений в реестре в тот же срок направляется уведомление с указанием причины.\n6. Заявитель вправе обжаловать действие или бездействие в порядке, установленном применимым законодательством.',note:'Ясная процедура не доказывает законность документа: нужны нормы о компетенции, сроках и способе предоставления. Агент должен указать ограничения, а не обещать отсутствие нарушений.'}
];
export function samplesPage(){return `<div class="stack"><section class="card stack"><p class="sample-badge">Эталон · доступен без API</p><h2>Эталонный учебный регламент</h2><p>Один подготовленный сценарий с тремя замечаниями и возражением по уточнённому сроку. Это демонстрация, а не анализ моделью.</p><div class="actions"><button type="button" class="btn primary" data-action="sample-start" data-sample="canonical">Проверить эталонный регламент</button><a class="btn" href="/api/sample-documents/canonical.docx" download>Скачать эталон DOCX</a></div></section><div class="notice"><h3>Учебные проекты регламентов</h3><p>Это синтетические тексты для проверки интерфейса и работы ИИ. Они не заменяют нормативную базу и не являются действующими НПА. Подготовленные ответы и реальные API-запуски отмечаются отдельно.</p></div>${SAMPLE_DOCUMENTS.map(d=>`<article class="card stack"><p class="eyebrow">УЧЕБНЫЙ ДОКУМЕНТ · ДЛЯ ПРОВЕРКИ ЧЕРЕЗ API</p><h2>${esc(d.title)}</h2><p>${esc(d.focus)}</p><details><summary>Текст и контрольный вопрос</summary><p class="sample-text">${esc(d.text)}</p><p>${esc(d.note)}</p></details><div class="actions"><a class="btn" href="/api/sample-documents/${d.id}.docx" download>Скачать DOCX</a><button type="button" class="btn primary" data-action="sample-start" data-sample="${d.id}">Проверить этот пример через API</button></div></article>`).join('')}<p class="muted">Кнопка проверки сразу подставляет выбранный текст. Эталон доступен как подготовленный сценарий; остальные примеры проверяются моделью через API. Для реального анализа потребуется настроенное API-подключение. Публичную действующую нормативную базу добавляет и проверяет владелец проекта.</p></div>`;}
